from gpiozero import PWMOutputDevice, TimeoutError
import time

# Define the GPIO pins for the PWM outputs
PWM_OUTPUTS = {
    "channel_1": PWMOutputDevice(1),
    "channel_2": PWMOutputDevice(2),
    "channel_3": PWMOutputDevice(3),
    "channel_4": PWMOutputDevice(4),
}

# Report the current PWM state for each output
def report_pwm_state(pwm_device, output_name):
    """Report the current PWM duty cycle for a given output."""
    try:
        current_duty_cycle = pwm_device.value
        print(f"Output {output_name}: duty cycle {current_duty_cycle:.2f}")
    except TimeoutError:
        # Handle a timeout during reading the PWM value
        print(f"Timeout reading output {output_name}")
    except Exception:
        # Handle any other unexpected error during reading
        print(f"Error reading output {output_name}: {e}")

def apply_pwm(pwm_device, output_name, duty_cycle):
    """Apply a given PWM duty cycle to an output."""
    try:
        pwm_device.value = duty_cycle
    except TimeoutError:
        # Handle a timeout during writing the PWM value
        print(f"Timeout writing output {output_name}")
    except Exception as e:
        # Handle any other unexpected error during writing
        print(f"Error writing output {output_name}: {e}")

def main():
    """Drive the PWM outputs and report their state."""
    try:
        # Create PWM devices for each output channel
        for output_name, pwm_device in PWM_OUTPUTS.items():
            pwm_device.start(0)
            print(f"Output {output_name}: starting PWM")

        # Repeat the PWM reporting and setting until interrupted
        while True:
            for output_name, pwm_device in PWM_OUTPUTS.items():
                report_pwm_state(pwm_device, output_name)
                apply_pwm(pwm_device, output_name, pwm_device.value)
            time.sleep(0.1)

    except KeyboardInterrupt:
        # Handle the user interrupt (Ctrl+C)
        print("Stopping PWM outputs")
    finally:
        # Ensure all PWM devices are stopped and released on exit
        for output_name, pwm_device in PWM_OUTPUTS.items():
            pwm_device.stop()
        print("PWM outputs stopped")

if __name__ == "__main__":
    main()

