import time
import io
import picamera2
from PIL import Image

# Camera configuration for the Raspberry Pi camera module
CAMERA_CONFIG = {
    "resolution": (1280, 720),
    "framerate": 30,
}

def capture_image():
    """Capture an image from the Raspberry Pi camera and return it as a PIL Image object."""
    try:
        # Create a camera object and capture the image
        camera = picamera2.Picamera2()
        camera.configure(CAMERA_CONFIG)
        camera.start()
        image_stream = io.BytesIO()
        camera.capture_file(image_stream, format="jpeg")
        camera.close()
        image_stream.seek(0)
        return Image.open(image_stream)
    except Exception as camera_error:
        # Report any camera error
        print("Camera capture failed:", camera_error)
        return None

def save_image(image, filename):
    """Save the captured image to the specified file."""
    try:
        # Save the image to the specified file
        image.save(filename)
        print("Image saved to", filename)
    except Exception as save_error:
        # Report any save error
        print("Image save failed:", save_error)

def main():
    """Continuously capture and save images until interrupted."""
    try:
        # Capture and save images until interrupted
        while True:
            image = capture_image()
            if image:
                save_image(image, "image.jpg")
            time.sleep(60)  # Wait 60 seconds before the next capture
    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("Image capture interrupted")
    finally:
        # Release the camera and close the image stream
        print("Releasing camera and closing stream")
        if 'camera' in locals():
            camera.close()

if __name__ == "__main__":
    main()

