import serial
import time

# UART settings for the device on the Raspberry Pi
UART_PORT = "/dev/ttyS0"
BAUD_RATE = 115200
TIMEOUT_SECONDS = 1

def open_uart(port_name):
    """Open the UART port and return the serial port object."""
    # Use the serial module to open the UART device
    return serial.Serial(port_name, baudrate=BAUD_RATE, timeout=TIMEOUT_SECONDS)

def read_device_data(serial_port):
    """Read a line of data from the serial device."""
    # Read a line from the UART port and return it
    try:
        raw_line = serial_port.readline().decode("ascii", errors="replace")
        return raw_line
    except serial.SerialException as serial_error:
        # Handle any serial communication errors
        print("Serial communication error:", serial_error)
        return None

def process_data(raw_line):
    """Process the received data line and return the result."""
    # Split the line into words and return the first one
    if raw_line:
        return raw_line.split(" ", 1)[0]
    return None

def main():
    """Main function to exchange data with the device."""
    serial_port = None
    try:
        # Open the UART port and read from the device
        serial_port = open_uart(UART_PORT)
        while True:
            received_line = read_device_data(serial_port)
            if received_line:
                processed_result = process_data(received_line)
                if processed_result:
                    print("Received:", processed_result)
            time.sleep(0.5)
    except KeyboardInterrupt:
        # Handle the user interrupt (Ctrl+C)
        print("Data exchange interrupted")
    finally:
        # Always release the serial port on exit
        if serial_port is not None:
            serial_port.close()

if __name__ == "__main__":
    main()

