#!/usr/bin/env python3

import time
import io
import picamera2
from PIL import Image

# Configure the camera module
try:
    camera = picamera2.Picamera2()
    camera.configure(camera.create_preview_configuration())
    camera.start()
except Exception as camera_error:
    print("Camera error: {}".format(camera_error))
    exit(1)


def capture_image():
    """Capture a single image from the camera."""
    try:
        # Capture the image
        image_stream = io.BytesIO()
        camera.capture_file(image_stream, format='jpeg')
        image_stream.seek(0)
        return image_stream.read()
    except Exception as capture_error:
        print("Capture error: {}".format(capture_error))
        return None


def validate_image(image_data):
    """Validate the image data."""
    # Check the image size and format
    if not (len(image_data) > 0 and len(image_data) <= 65536):
        return False
    return True


def process_image(image_data):
    """Process the image data."""
    # Convert the image data to a PIL Image object
    try:
        pil_image = Image.open(io.BytesIO(image_data))
        # Resize the image to a smaller size
        pil_image = pil_image.resize((128, 128))
        return pil_image
    except Exception as image_error:
        print("Image processing error: {}".format(image_error))
        return None


def main():
    """Main function to capture and process images."""
    # Keep the program running until interrupted
    while True:
        image_data = capture_image()
        if image_data:
            pil_image = process_image(image_data)
            if pil_image:
                # Check the image validity
                if validate_image(pil_image):
                    print("Image is valid")
                else:
                    print("Image is invalid")
            else:
                print("Failed to process image")
        else:
            print("Failed to capture image")
        time.sleep(1)


if __name__ == "__main__":
    main()

import serial
import time

# UART settings for the device on the Raspberry Pi
UART_PORT = "/dev/ttyS0"
BAUD_RATE = 115200
TIMEOUT_SECONDS = 1

def open_uart(port_name):
    """Open the UART port and return the serial port object."""
    # Use the serial module to open the UART device
    return serial.Serial(port_name, baudrate=BAUD_RATE, timeout=TIMEOUT_SECONDS)

def read_device_data(serial_port):
    """Read a line of data from the serial device."""
    # Read a line from the UART port and return it
    try:
        return serial_port.readline().decode("ascii", errors="replace")
    except serial.SerialException as serial_error:
        # Handle a serial communication failure
        print("Serial communication error:", serial_error)
        return None

def process_data(raw_data):
    """Process the received data and return a formatted string."""
    # Split the data into a list of words
    words = raw_data.split()
    # Check if the data is a valid command
    if words and words[0] == "SET":
        return "Command received: " + " ".join(words[1:])
    return None

def main():
    """Main function to exchange data with the device."""
    # Open the UART port for the Raspberry Pi
    serial_connection = open_uart(UART_PORT)
    try:
        # Continuously read and process data from the device
        while True:
            received_data = read_device_data(serial_connection)
            if received_data:
                processed_data = process_data(received_data)
                if processed_data:
                    print("Received:", processed_data)
            time.sleep(0.1)
    except KeyboardInterrupt:
        # Stop the program gracefully on Ctrl+C
        print("Data exchange stopped")
    finally:
        # Always release the serial port
        serial_connection.close()

if __name__ == "__main__":
    main()

import io
import time
from picamera2 import Picamera2

# Configure the camera for the Raspberry Pi
try:
    picam2 = Picamera2()
    picam2.configure(picam2.create_preview_configuration())
    picam2.start()
    print("Camera initialized")
except Exception as camera_error:
    print("Failed to initialize camera:", camera_error)
    exit(1)


def capture_image():
    """Capture a single image from the camera and return it as a byte stream."""
    try:
        # Capture the image and convert it to a byte stream
        stream = io.BytesIO()
        picam2.capture_file(stream, format='jpeg')
        stream.seek(0)
        return stream
    except Exception as capture_error:
        print("Failed to capture image:", capture_error)
        return None


def validate_image(image_stream):
    """Check the image validity and return True if it passes, False otherwise."""
    try:
        # Read the image and check its dimensions
        image_data = image_stream.read()
        if len(image_data) > 0:
            width, height = image_data.shape
            if width > 0 and height > 0:
                return True
        return False
    except Exception as validation_error:
        print("Failed to validate image:", validation_error)
        return False


