    except serial.SerialException as e:
        print(f"Error opening UART: {e}")
        return None

def read_device_data(uart_port, timeout_seconds):
    """Read a line of data from the UART device."""
    if not uart_port:
        return None
    try:
        return uart_port.readline(timeout_seconds)
    except serial.SerialException as e:
        print(f"UART read error: {e}")
        return None

def validate_reading(raw_data, expected_value, min_value, max_value):
    """Check if the received data matches the expected value within the range."""
    if raw_data is None:
        return False
    try:
        return min_value <= int(raw_data) <= max_value
    except ValueError:
        print("Invalid data received from device.")
        return False

def process_data(raw_data, expected_value, min_value, max_value):
    """Return the processed value if valid, otherwise return None."""
    if validate_reading(raw_data, expected_value, min_value, max_value):
        return expected_value
    return None

def main():
    """Main function to exchange data with the device."""
    uart_connection = open_uart(UART_PORT, BAUD_RATE, TIMEOUT)
    if not uart_connection:
        return

