def read_dht22(data_pins):
    """Read a DHT22 temperature and humidity sensor."""
    # Create a DHT22 object for each data pin
    dht_sensors = [adafruit_dht.DHT22(pin) for pin in data_pins]
    # Attempt to read the sensor multiple times
    for attempt_index in range(3):
        for sensor in dht_sensors:
            if sensor.is_valid():
                # Return the temperature and humidity values
                return sensor.temperature, sensor.humidity
        # If the reading fails, report the error and continue
        print("DHT22 reading failed, retrying...")
        time.sleep(1)
    # If all readings failed, report an error
    return None, None

def report_state(temperature, humidity):
