        print("Error opening UART port:", e)
        return None

def read_device_data(uart_port, timeout_seconds):
    """Read a line of data from the UART device."""
    if not uart_port:
        return None
    try:
        return uart_port.readline(timeout_seconds).decode("ascii", errors="replace").strip()
    except serial.SerialException as e:
        print("Error reading from UART:", e)
        return None

def validate_data(data_string):
    """Check if the data string is valid."""
    return data_string and data_string.isnumeric()

def process_data(data_string):
    """Process the received data string."""
    print("Received:", data_string)
    return data_string

def main():
    """Main function to exchange data with the device."""
    uart_connection = open_uart(UART_PORT, BAUD_RATE)
    if not uart_connection:
        return

    try:
        while True:
            received_data = read_device_data(uart_connection, TIMEOUT)
            if received_data:
                processed_data = process_data(received_data)
                print("Processed:", processed_data)
            time.sleep(0.5)
    except KeyboardInterrupt:
