# Set up the GPIO pins for the PWM output and the relay module
try:
    pwm_output = PWMOutputDevice(PWM_PIN, frequency=1000)
    relay_module = GPIO.PWM(RELAY_PIN, 1000)
    relay_module.start(0)
except Exception as device_error:
    print("Error initializing GPIO or PWM device:", device_error)
    exit(1)


def apply_pwm(duty_cycle):
    """Apply a given PWM duty cycle to the output."""
    try:
        pwm_output.duty_cycle = duty_cycle
        print("PWM duty cycle set to", duty_cycle)
    except Exception as apply_error:
        print("Error applying PWM:", apply_error)


def report_state():
    """Report the current state of the PWM output."""
    try:
        print("PWM output is:", pwm_output.is_active())
    except Exception as report_error:
        print("Error reporting PWM state:", report_error)


def main_loop():
    """Main loop to continuously apply and report the PWM output."""
    try:
        while True:
            apply_pwm(50)
            report_state()
            time.sleep(1)
    except KeyboardInterrupt:
        print("PWM loop interrupted by user")
    finally:
        # Stop the PWM output and release the GPIO pins
        pwm_output.stop()
        GPIO.cleanup()
        print("PWM output stopped and GPIO cleaned up")


